import { ManufacturersComponent } from './manufacturer/manufacturers.component';
import { RatingsComponent } from './rating/ratings.component';
import { ReportComponent } from './report/report.component';
import { NotMigratedComponent } from './not-migrated.component';

/**
 * Route paths are the GWTP name tokens of the original application
 * (`NameTokens.java`): `manufacturer`, `rating`, `report`, `cars`, `stats`.
 * With `GwtHashLocationStrategy` they are addressed as `#manufacturer`,
 * `#rating`, ... exactly like the GWT history tokens.
 */
