import { Injectable } from '@angular/core';
import { CarDto, ManufacturerDto, ManufacturerRatingDto, RatingDto } from './models';

/** Root of the carstore REST API, as defined by `ApiPaths.ROOT`. */
const API_ROOT = '/api';

/**
 * Reads a response body while keeping 64-bit datastore ids exact: every
 * numeric `"id"` property is turned into a string before `JSON.parse`, so
 * no id ever goes through a lossy JavaScript number.
 */
function parseBody<T>(text: string): T {
    const idSafe = text.replace(/"id"\s*:\s*(-?\d+)/g, '"id":"$1"');
    return JSON.parse(idSafe) as T;
}

/**
 * Thin typed client for the existing JAX-RS API of the carstore backend
 * (`ManufacturersResource`, `RatingResource`, `CarsResource`,
 * `SessionResource`). No endpoints are invented; every path comes from
 * `ApiPaths`.
 */
@Injectable({ providedIn: 'root' })
export class ApiService {
    async getManufacturers(): Promise<ManufacturerDto[]> {
        return this.get<ManufacturerDto[]>('/manufacturers');
    }

    async saveManufacturer(manufacturer: ManufacturerDto): Promise<ManufacturerDto> {
        return this.post<ManufacturerDto>('/manufacturers', manufacturer);
    }

    async deleteManufacturer(id: string): Promise<void> {
        return this.delete(`/manufacturers/${id}`);
    }

    async getAverageRatings(): Promise<ManufacturerRatingDto[]> {
        return this.get<ManufacturerRatingDto[]>('/manufacturers/ratings');
    }

    async getRatings(): Promise<RatingDto[]> {
        return this.get<RatingDto[]>('/ratings');
    }

    async saveRating(rating: RatingDto): Promise<RatingDto> {
        return this.post<RatingDto>('/ratings', rating);
    }

    async deleteRating(id: string): Promise<void> {
        return this.delete(`/ratings/${id}`);
    }

    async getCars(): Promise<CarDto[]> {
        return this.get<CarDto[]>('/cars?offset=0&limit=-1');
    }

    async logout(): Promise<void> {
        return this.delete('/session');
    }

    private async get<T>(path: string): Promise<T> {
        return this.request<T>(path, 'GET');
    }

    private async post<T>(path: string, body: unknown): Promise<T> {
        return this.request<T>(path, 'POST', body);
    }

    private async delete(path: string): Promise<void> {
        await this.request<void>(path, 'DELETE');
    }

    private async request<T>(path: string, method: string, body?: unknown): Promise<T> {
        const response = await fetch(API_ROOT + path, {
            method,
            headers:
                body === undefined
                    ? { Accept: 'application/json' }
                    : { Accept: 'application/json', 'Content-Type': 'application/json' },
            body: body === undefined ? undefined : JSON.stringify(body),
        });

        if (!response.ok) {
            throw new Error(`${method} ${path} failed with status ${response.status}`);
        }

        const text = await response.text();
        return text.length === 0 ? (undefined as T) : parseBody<T>(text);
    }
}
