import { Injectable, signal } from '@angular/core';

export type MessageKind = 'SUCCESS' | 'ERROR';

export interface AppMessage {
    /** Local identity used for list tracking; not rendered. */
    messageId: number;
    text: string;
    kind: MessageKind;
}

/** `MessageCloseDelay.DEFAULT` in the GWT application. */
const DEFAULT_CLOSE_DELAY_MS = 5000;

/**
 * Equivalent of the GWT `MessagesPresenter` / `DisplayMessageEvent` bus:
 * screens publish success or error messages and the messages widget
 * displays them, each one auto-closing after five seconds.
 */
@Injectable({ providedIn: 'root' })
export class MessagesService {
    private nextMessageId = 0;
    private readonly messageList = signal<AppMessage[]>([]);
    readonly messages = this.messageList.asReadonly();

    success(text: string): void {
        this.add(text, 'SUCCESS');
    }

    error(text: string): void {
        this.add(text, 'ERROR');
    }

    close(message: AppMessage): void {
        this.messageList.update((messages) =>
            messages.filter((candidate) => candidate.messageId !== message.messageId),
        );
    }

    private add(text: string, kind: MessageKind): void {
        const message: AppMessage = { messageId: ++this.nextMessageId, text, kind };
        this.messageList.update((messages) => [...messages, message]);
        setTimeout(() => this.close(message), DEFAULT_CLOSE_DELAY_MS);
    }
}
