/**
 * TypeScript counterparts of the Java DTOs in
 * `com.gwtplatform.carstore.shared.dto`.
 *
 * Jackson serializes Java bean properties, so the JSON field names are
 * `id`, `name`, `car`, `rating`, ... exactly as in the Java classes.
 *
 * Ids are kept as strings: the backend uses 64-bit datastore ids that do
 * not always fit into a JavaScript number, so `ApiService` reads them as
 * strings (Jackson happily coerces `"123"` back to `Long` on input).
 */
export interface CarPropertiesDto {
    id: string | null;
    someString?: string | null;
    someNumber?: number | null;
    someDate?: string | null;
    car?: CarDto | null;
}

export interface ManufacturerDto {
    id: string | null;
    name: string;
    cars?: CarDto[] | null;
}

export interface CarDto {
    id: string | null;
    model: string;
    manufacturer?: ManufacturerDto | null;
    ratings?: RatingDto[] | null;
    carProperties?: CarPropertiesDto | null;
}

export interface RatingDto {
    id: string | null;
    rating: number | null;
    car: CarDto | null;
}

export interface ManufacturerRatingDto {
    manufacturer: string;
    rating: number;
}

/**
 * Same rendering as `RatingDto.toString()` in the GWT application:
 * `manufacturer + "/" + model`, e.g. `Honda/Accord`.
 */
export function carLabel(car: CarDto | null): string {
    if (car === null) {
        return '';
    }
    const manufacturer = car.manufacturer?.name ?? '';
    return `${manufacturer}/${car.model}`;
}
