import { Injectable } from '@angular/core';
import { HashLocationStrategy } from '@angular/common';

/**
 * A hash based location strategy that keeps the exact URL shape of the
 * original GWTP application: history tokens are plain name tokens with no
 * leading slash, e.g. `.../ng/#manufacturer` (see `NameTokens.java`).
 *
 * `HashLocationStrategy` would produce `#/manufacturer` instead, which
 * changes the URLs the application is reached with.
 */
@Injectable()
export class GwtHashLocationStrategy extends HashLocationStrategy {
    override path(includeHash = false): string {
        const token = super.path(includeHash);
        const trimmed = token.replace(/^\/+/, '');
        return trimmed.length > 0 ? `/${trimmed}` : '';
    }

    override prepareExternalUrl(internal: string): string {
        const token = internal.replace(/^\/+/, '');
        return `#${token}`;
    }
}
