import { Component, inject } from '@angular/core';
import { AppMessage, MessagesService } from '../core/messages.service';

/**
 * Messages widget migrated from `widget/message/`: success and error
 * messages rendered as `MessageWidget`s. Like `HTMLPanel.ensureDebugId`,
 * every success message carries the id `gwt-debug-successMessage` and
 * every error message `gwt-debug-errorMessage`. Clicking the `X` span
 * removes the message from the DOM, and each message closes itself after
 * `MessageCloseDelay.DEFAULT` (5 seconds).
 */
@Component({
    selector: 'app-messages',
    standalone: true,
    template: `
        @for (message of messages(); track message.messageId) {
            <div
                class="message"
                [class.success]="message.kind === 'SUCCESS'"
                [class.error]="message.kind === 'ERROR'"
                [id]="message.kind === 'SUCCESS' ? 'gwt-debug-successMessage' : 'gwt-debug-errorMessage'">
                <span>{{ message.text }}</span>
                <span class="close" (click)="close(message)">X</span>
            </div>
        }
    `,
    styles: `
        .message {
            position: relative;
            width: 260px;
            margin: 4px auto;
            padding: 8px 30px 8px 12px;
            border-radius: 4px;
            font-size: 13px;
            text-align: center;
        }

        .message.success {
            background: #e2f8e2;
            border: 1px solid #57a957;
            color: #2d742d;
        }

        .message.error {
            background: #fdeaea;
            border: 1px solid #c05858;
            color: #a12622;
        }

        .close {
            position: absolute;
            top: 7px;
            right: 9px;
            font-weight: bold;
            cursor: pointer;
        }
    `,
})
export class MessagesComponent {
    private readonly messagesService = inject(MessagesService);
    readonly messages = this.messagesService.messages;

    close(message: AppMessage): void {
        this.messagesService.close(message);
    }
}
